"Tailscale 장치 ID를 읽을 수 없습니다. 공식 클라이언트를 업데이트하고 로그인하세요.":"Cannot read the Tailscale device identity. Update the official client and sign in.",
"Tailscale URL가 감지되었습니다. 저장하고 게이트웨이를 시작한 다음 고정된 항목을 확인하십시오.":"Tailscale URL detected. Save, start the gateway, then check the fixed entry.",
"Tailscale 계정 또는 장치 주소가 변경되었습니다. 연결을 다시 감지하고 저장하십시오.":"The Tailscale account or device address changed. Detect and save the connection again.",
"Tailscale 고정 항목을 시작하는 중…":"Starting the Tailscale fixed entry…",
"다른 서비스에서는 이 Tailscale 포트를 사용합니다. 다른 포트를 선택하십시오. 기존 설정은 덮어쓰이지 않습니다.":"Another service uses this Tailscale port. Choose another port; existing settings will not be overwritten.",
"계속 연결하려면 Tailscale HTTPS 또는 유입경로 인증을 완료하세요.":"Complete Tailscale HTTPS or Funnel authorization to continue connecting.",
"Tailscale 항목이 시작되었습니다. 고정된 항목을 확인하고 휴대폰에서 인증하세요.":"Tailscale entry started. Check the fixed entry and verify on your phone.",
"Tailscale 항목의 연결이 끊어졌습니다. 재시도 중입니다.":"Tailscale entry disconnected. Retrying.",
"Tailscale 항목이 연결을 유지하지 못했습니다. 클라이언트, 네트워크 및 유입경로 인증을 확인하세요.":"Tailscale entry did not stay connected. Check the client, network and Funnel authorization.",
"Tailscale 고정 항목이 중지되었습니다.":"Tailscale fixed entry stopped",
"유효한 Tailscale 액세스 범위를 선택하세요.":"Select a valid Tailscale access scope.",
"Tailscale HTTPS 포트는 443, 8443 또는 10000이어야 합니다.":"Tailscale HTTPS ports must be 443, 8443 or 10000.",
"Tailscale 장치 ID가 잘못되었습니다. 다시 감지합니다.":"Invalid Tailscale device identity. Detect again.",
"감지를 사용하여 이 컴퓨터의 Tailscale 주소를 읽으십시오.":"Use detection to read this computer's Tailscale address.",
"게이트웨이당 하나의 Tailscale 항목만 활성화합니다.":"Enable only one Tailscale entry per gateway.",
"공개 유입경로에 액세스하려면 게이트웨이 로그인이 필요합니다. 휴대폰은 여전히 ​​QR 코드로 페어링할 수 있습니다.":"Public Funnel access requires gateway sign-in. Phones can still pair by QR code.",
"Tailscale 연결을 선택합니다.":"Select a Tailscale connection.",
"Tailscale 클라이언트를 사용하여 로그인합니다. 항목을 시작한 후 추가 승인이 여기에 표시됩니다.":"Sign in using the Tailscale client. Any additional approval will appear here after starting the entry.",
"Tailscale 인증이 잘못되었습니다. URL. 다시 감지합니다.":"Invalid Tailscale authorization URL. Detect again.",
"Tailscale 인증 페이지가 열렸습니다.":"Tailscale authorization page opened.",
"다시 확인":"Check again",
"Claude 연결 설정":"Claude connection setup",
"처음 사용하기 전에 다음 단계를 완료하세요. 접근성과 폴더 신뢰는 별도의 권한입니다. 게이트웨이는 폴더 신뢰를 부여하지 않습니다.":"Complete these steps before first use. Accessibility and folder trust are separate permissions. The gateway will not grant folder trust for you.",
"접근성 액세스 확인 및 요청":"Check and request Accessibility access",
"연결 폴더 복사":"Copy connection folder",
