"나중에 설정하세요":"Set up later",
"접근성: 부여됨":"Accessibility: granted",
"접근성: Claude가 아닌 이 게이트웨이 앱에 대한 액세스 권한을 부여하세요.":"Accessibility: grant access to this gateway app, not Claude",
"개발자 모드: 활성화됨":"Developer mode: enabled",
"개발자 모드: Claude에서 확인":"Developer mode: confirm in Claude",
"폴더 신뢰: 현재 연결로 확인됨":"Folder trust: verified by the current connection",
"폴더 신뢰: Claude Code에서 아래 폴더를 선택하고 신뢰하는지 확인하세요. 그런 다음 연결 초기화를 클릭합니다.":"Folder trust: select the folder below in Claude Code and confirm that you trust it. Then click Initialize connection.",
"이제 권한을 설정할 수 있습니다. 연결을 초기화하기 전에 게이트웨이를 시작하십시오.":"You can set up permissions now. Start the gateway before initializing the connection.",
