  "게이트웨이에 연결할 수 없습니다. 연결을 확인하고 다시 로드하세요.": "Could not connect to the gateway. Check your connection and reload.",
"클라이언트 프로세스가 변경되었습니다. 종료하기 전에 다시 한번 확인해 보세요(quit:changed).":"The client process changed. Check it again before quitting (quit: changed).",
"macOS 종료 결과를 알 수 없습니다. 클라이언트 상태를 확인하세요. 프로세스가 강제로 중지되지 않았습니다(종료: 시간 초과).":"The macOS quit result is unknown. Check the client status; no process was forcibly stopped (quit: timeout).",
