"클라이언트가 종료 요청을 거부했습니다. 프롬프트를 확인하세요. 프로세스가 강제로 중지되지 않았습니다(종료: 거부됨).":"The client declined the quit request. Check its prompts; no process was forcibly stopped (quit: rejected).",
"macOS 종료 결과를 확인할 수 없습니다. 클라이언트 상태를 확인하세요(quit:invalid-response).":"Unable to verify the macOS quit result. Check the client status (quit: invalid-response).",
