"저장된 연결을 삭제하시겠습니까? 이렇게 하면 게이트웨이 복사본만 제거되고 데스크톱 앱은 로그아웃되지 않습니다.":"Delete this saved connection? This only removes the gateway copy and does not sign out the desktop app.",
