"엔드포인트는 Anthropic 메시지 API를 지원해야 합니다. 지원되는 Claude 모델 ID를 입력하세요. 자격 증명은 이 컴퓨터에 남아 있습니다. 저장해도 연결이 전환되지 않습니다.":"The endpoint must support the Anthropic Messages API. Enter its supported Claude model IDs. Credentials stay on this computer; saving does not switch the connection.",
