"기존 프로젝트를 선택하거나 프로젝트 없음을 선택하여 독립적인 채팅을 만듭니다. 데스크톱 앱에서 이 채팅이 열립니다.":"Select an existing project, or choose No project to create an independent chat. The desktop app will open this chat.",
