  "공급자가 지원되지 않는 모델 목록을 반환했습니다. 모델 ID를 수동으로 입력하세요.": "The provider returned an unsupported model list. Enter a model ID manually.",
  "공급자가 사용 가능한 모델을 반환하지 않았습니다. 모델 ID를 수동으로 입력하세요.": "The provider returned no usable models. Enter a model ID manually.",
  "액세스가 거부되었습니다. API 키 및 모델 목록 권한을 확인하세요.": "Access was denied. Check the API key and model-list permissions.",
  "공급자에게 리디렉션이 필요합니다. 마지막 API URL를 입력하고 다시 시도하세요.": "The provider requires a redirect. Enter the final API URL and retry.",
  "모델 목록을 확인할 수 없습니다. API URL를 확인하거나 ID 모델을 수동으로 입력하세요.": "The model list is unavailable. Check the API URL or enter a model ID manually.",
  "공급자에게 연결할 수 없습니다. API URL, 네트워크 및 인증서를 확인하세요.": "Cannot reach the provider. Check the API URL, network and certificates.",
  "Codex 구성 디렉터리의 전체 경로를 입력합니다.": "Enter the full path to a Codex configuration directory.",
  "이 디렉터리에는 config.toml 또는 auth.json이 없습니다.": "No config.toml or auth.json was found in this directory.",
  "로컬 구성이 변경되었습니다. 다시 스캔하세요.": "The local configuration changed. Scan it again.",
  "추가 요청 설정이 있는 공급자 가져오기는 지원되지 않습니다.": "Importing providers with additional request settings is not supported.",
  "이 공급자는 API 응답을 사용하지 않으며 가져올 수 없습니다.": "This provider does not use the Responses API and cannot be imported.",
  "사용 가능한 API 키 또는 URL를 찾을 수 없습니다. 환경 변수를 확인하거나 수동으로 추가하세요.": "No usable API key or URL was found. Check the environment variable or add it manually.",
  "시스템 자격 증명 저장소 로그인은 여기에 복사할 수 없습니다. 공식 로그인을 통해 추가하세요.": "A system credential-store login cannot be copied here. Add it through official sign-in.",
  "다시 스캔하고 가져올 수 있는 구성을 선택하십시오.": "Scan again and choose an importable configuration.",
