  "인증 없이는 계정 전환이 불가능합니다. 데스크톱 앱을 사용하세요.": "Account switching is unavailable without authentication. Use the desktop app.",
  "로그인 준비 중": "Preparing sign-in",
  "이 컴퓨터의 브라우저에서 공식 로그인을 완료하세요.": "Complete official sign-in in this computer’s browser",
  "계정이 추가됨": "Account added",
  "로그인이 완료되지 않았습니다. 다시 시도해 주세요.": "Sign-in did not complete. Please try again.",
  "공식 로그인 열기": "Open official sign-in",
  "로그인 취소": "Cancel sign-in",
  "계정을 관리하려면 업데이트된 게이트웨이를 시작하세요.": "Start the updated gateway to manage accounts.",
  "계정 전환 또는 복구가 보류 중입니다. 채팅 작업이 일시적으로 일시 중지되었습니다.": "An account switch or recovery is pending. Chat actions are temporarily paused.",
  "무시하다": "Ignore",
  "무시하면 확인되지 않은 기록만 무시됩니다. 메시지를 철회하거나 다시 보내지는 않습니다. 먼저 채팅 기록을 확인하세요.": "Ignoring only dismisses this unconfirmed record. It will not retract or resend the message. Check the chat history first.",
  "확인되지 않은 전송 기록만 무시할 수 있습니다.": "Only unconfirmed send records can be ignored.",
  "확인되지 않은 기록은 무시됩니다.": "Unconfirmed record ignored",
  "이 확인되지 않은 기록은 무시되었습니다. 다시 보내기 전에 메시지를 새로 고치고 편집하세요.": "This unconfirmed record was ignored. Refresh and edit the message before sending again.",
  "온라인 가이드": "Online guide",
  "스킬을 로드할 수 없습니다. 다시 시도하려면 새로 고침을 클릭하세요.": "Could not load Skills. Click Refresh to retry.",
  "스킬링크 대상이 변경되었습니다. 목록을 새로 고치고 다시 선택하세요.": "The Skill link target changed. Refresh the list and select it again.",
  "이 채팅은 이전 공급자를 유지합니다. 다시 전환하거나 새 채팅을 시작하세요.": "This chat retains its previous provider. Switch back or start a new chat.",
  "전환하기 전에 대기 중인 메시지와 확인되지 않은 제출을 해결하세요.": "Resolve queued messages and unconfirmed submissions before switching.",
  "전환하기 전에 실행 중인 작업과 보류 중인 승인을 완료하세요.": "Finish running tasks and pending approvals before switching.",
  "먼저 데스크톱 앱에서 Codex 데스크톱 실행 파일을 선택하세요.": "Choose the Codex desktop executable in the desktop app first.",
  "전환이 수행되지 않았습니다. 로그인, 구성 제한 및 데스크톱 실행 파일을 확인하세요.": "Switch not performed. Check sign-in, configuration restrictions and the desktop executable.",
  "전환에 실패했습니다. 이전 계정이 복원되었습니다. 데스크톱 앱을 확인하거나 다시 로그인하세요.": "Switch failed; the previous account was restored. Check the desktop app or sign in again.",
  "자동 복구에 실패했습니다. 데스크톱 앱에서 이전 계정을 복원하세요.": "Automatic recovery failed. Restore the previous account in the desktop app.",
  "이전 스위치가 중단되었습니다. 데스크톱 앱에서 이전 계정을 복원하세요.": "The previous switch was interrupted. Restore the previous account in the desktop app.",
  "이 계정을 삭제하기 전에 다른 계정으로 전환하세요.": "Switch to another account before deleting this one.",
  "이 API를 편집하기 전에 다른 계정으로 전환하세요.": "Switch to another account before editing this API.",
  "다시 로그인하기 전에 다른 계정으로 전환하세요.": "Switch to another account before signing in again.",
  "먼저 대기 중인 로그인을 완료하거나 취소하세요.": "Complete or cancel the pending sign-in first.",

  "PushPlus 알림": "PushPlus notifications",
  "LAN 액세스 범위": "LAN access scope",
  "모든 IPv4 주소": "All IPv4 addresses",
  "선택된 IPv4 주소만": "Selected IPv4 addresses only",
  "WSL 또는 VMware와 같은 가상 어댑터를 제외할 주소를 선택합니다. 적용하려면 게이트웨이를 저장하고 다시 시작하세요. 주소가 변경되면 다시 선택하세요. 다른 어댑터는 자동으로 열리지 않습니다.": "Select addresses to exclude virtual adapters such as WSL or VMware. Save and restart the gateway to apply. Reselect if an address changes; other adapters will not be opened automatically.",
  "로컬 브라우저 접근 허용(127.0.0.1 / localhost)": "Allow local browser access (127.0.0.1 / localhost)",
  "끄면 로컬 URL이 숨겨지고 로컬 브라우저 액세스가 차단됩니다. 데스크탑 상태 확인 및 HTTPS 터널은 내부 루프백 연결을 유지합니다.": "When off, local URLs are hidden and local browser access is blocked. Desktop status checks and HTTPS tunnels retain an internal loopback connection.",
  "프로젝트 홈 ↗": "Project home ↗",
  "문제 신고 ↗": "Report an issue ↗",
  "PR 기부 ↗": "Contribute a PR ↗",
  "현재는 이용할 수 없습니다": "Currently unavailable",
  "LAN IPv4 주소를 찾을 수 없습니다.": "No LAN IPv4 addresses found",
  "유효한 LAN IPv4 주소를 선택하세요.": "Select valid LAN IPv4 addresses",
  "선택한 주소를 사용할 수 없거나 해당 포트가 사용 중입니다. 어댑터와 포트를 확인하세요. 다른 주소는 자동으로 열리지 않습니다.": "A selected address is unavailable or its port is in use. Check your adapters and port; other addresses will not be opened automatically.",
  "로컬 브라우저 액세스가 비활성화되었습니다.": "Local browser access is disabled",
  "로컬 상태 확인만 허용됩니다.": "Only local status checks are allowed",
  "WeChat으로 PushPlus에 로그인하고 해당 서비스 계정을 팔로우한 후 실명 확인을 완료하고 프로필에서 토큰을 복사하세요. 채널을 활성화 및 저장하고 테스트 알림을 보낸 다음 설정에서 전체 알림을 선택하거나 개별 채팅에 대한 알림을 조정하세요.": "Sign in to PushPlus with WeChat, follow its service account, complete real-name verification, and copy the token from your profile. Enable and save the channel, send a test notification, then choose global notifications in Settings or adjust reminders for individual chats.",
  "PushPlus에는 CNY 3.90부터 유료 실명 확인이 필요합니다. 인증된 사용자는 회원가입 없이도 기본수당을 사용할 수 있습니다. 현재 가격은 공식 페이지를 확인하세요.": "PushPlus requires paid real-name verification, starting at CNY 3.90. Verified users can use the basic allowance without a membership. Check the official page for current pricing.",
  "일반 검증된 사용자의 경우 WeChat 채널은 하루에 200개, 분당 5개의 요청을 허용하며 시간당 최대 3개의 동일한 메시지를 허용합니다. 실패한 요청도 포함됩니다. 한도를 초과하면 배송이 중단될 수 있습니다.": "For ordinary verified users, the WeChat channel allows 200 requests per day and 5 per minute, with up to 3 identical messages per hour. Failed requests also count. Exceeding limits may suspend delivery.",
  "PushPlus 웹사이트 및 토큰 ↗": "PushPlus website and token ↗",
  "검증 및 가격 ↗": "Verification and pricing ↗",
  "할당량 및 비율 제한 ↗": "Quotas and rate limits ↗",
  "PushPlus 활성화": "Enable PushPlus",
