  "채팅 이름 바꾸기": "Rename chat",
  "채팅 이름이 변경되었습니다.": "Chat renamed",
  "저장되었습니다. 유지하려면 비워 두세요.": "Saved; leave blank to keep",
  "PushPlus 토큰을 입력하세요": "Enter your PushPlus token",
  "저장된 설정 테스트": "Test saved settings",
  "PushPlus 설정이 저장되었습니다.": "PushPlus settings saved",
  "PushPlus가 테스트 알림을 수락했습니다. 휴대전화를 확인하세요.": "PushPlus accepted the test notification. Check your phone.",
  "PushPlus 웹사이트에서 토큰을 받으세요. 저장한 후 팔로우하려는 각 채팅에서 알림을 활성화하세요.": "Get a token from the PushPlus website. After saving, enable reminders in each chat you want to follow.",
  "먼저 PushPlus, Bark 또는 ntfy를 구성하고 활성화합니다.": "Configure and enable PushPlus, Bark, or ntfy first.",
  "잘못된 PushPlus 토큰": "Invalid PushPlus token",
  "PushPlus를 활성화하기 전에 토큰을 입력하세요.": "Enter a token before enabling PushPlus",
  "먼저 PushPlus 토큰을 구성하세요.": "Configure your PushPlus token first",
  "PushPlus가 알림을 거부했습니다. 토큰과 네트워크를 확인하세요.": "PushPlus rejected the notification. Check your token and network.",
  "PushPlus 테스트가 실패했습니다. 토큰과 네트워크를 확인하세요.": "PushPlus test failed. Check your token and network.",
  "이 게이트웨이에서는 알림이 활성화되지 않았습니다.": "Notifications are not enabled on this gateway",
