  "소스 채팅:": "Source chat: ",
  "귀하의 브라우저가 자동 복사를 차단했습니다. 텍스트를 선택하고 시스템 복사 작업이나 키보드 단축키를 사용합니다.": "Your browser blocked automatic copying. Select the text and use the system Copy action or keyboard shortcut.",
  "이 메시지를 바꾸고 새 응답을 생성하세요. 이전에 실행한 파일 변경 사항과 명령은 그대로 유지됩니다.": "Replace this message and generate a new response. Previously executed file changes and commands will remain.",
  "이번 차례까지 기록을 유지하고 다음 메시지를 기다리세요. 두 채팅 모두 동일한 작업 디렉터리를 공유합니다.": "Keep history through this turn and wait for your next message. Both chats share the same working directory.",
  "원래 채팅을 유지하고 새 분기에서 편집 내용을 사용하여 이번 턴을 다시 생성하세요. 두 채팅 모두 작업 디렉터리를 공유합니다.": "Keep the original chat and regenerate this turn with your edits in a new branch. Both chats share the working directory.",
  "채팅이 바뀌었습니다. 메시지를 다시 선택하세요.": "The chat changed. Select the message again.",
  "메시지가 변경되었습니다. 다시 열어보세요.": "The message changed. Open it again.",
  "대화가 바뀌었습니다. 새로고침하고 다시 시도하세요.": "The conversation changed. Refresh and try again.",
  "전체 텍스트를 로드할 수 없습니다. 다시 시도해 보세요.": "Could not load the complete text. Try again.",
  "결과는 확인되지 않았습니다. 먼저 채팅 기록을 확인하세요. 다시 제출하면 작업이 반복되지 않습니다.": "The result is not confirmed. Check the chat history first. Submitting again will not repeat the operation.",
  "브랜치가 생성되었으며 채팅 목록에서 사용할 수 있습니다.": "The branch was created and is available in the chat list.",
  "분기가 생성되었지만 편집 내용이 전송되지 않았습니다. 계속하려면 마지막 메시지를 연결하고 편집하세요.": "The branch was created, but your edit was not sent. Connect and edit its last message to continue.",
  "지점이 생성되었습니다.": "Branch created",
  "새 지점에서 재전송": "Resent in the new branch",
  "메시지 재전송": "Message resent",
  "제출 중…": "Submitting…",
  "잘못된 메시지 작업": "Invalid message action",
  "ID 작업은 다른 콘텐츠에 재사용할 수 없습니다.": "An operation ID cannot be reused for different content",
  "이 메시지에는 이 작업을 수행할 수 없습니다.": "This action is unavailable for this message",
  "편집하거나 분기하기 전에 현재 회전을 중지하세요.": "Stop the current turn before editing or branching",
  "여기에서는 최신 메시지만 편집할 수 있습니다. 새 지점에서 편집을 사용하십시오.": "Only the latest message can be edited here. Use Edit in new branch.",
  "원래 모델 설정을 사용할 수 없습니다. 먼저 다시 연결하세요.": "Original model settings are unavailable. Reconnect first.",
  "안전한 대화 분기를 사용하려면 데스크톱 Codex 앱을 업데이트하세요.": "Update the desktop Codex App to use safe conversation branching.",
  "잘못된 분기 결과입니다. 데스크톱 채팅 목록을 확인하세요.": "Invalid branch result. Check the desktop chat list.",
  "지점 위치는 확인되지 않았습니다. 다시 시도하기 전에 데스크톱 채팅 목록을 확인하세요.": "The branch position was not confirmed. Check the desktop chat list before trying again.",
  "지점 공급자가 일치하지 않습니다. 데스크톱 채팅 목록을 확인하세요.": "The branch provider does not match. Check the desktop chat list.",

