  "업데이트된 앱이 준비되지 않았습니다.": "The updated app did not become ready.",
  "게이트웨이 상태가 변경되었습니다. 업데이트가 취소되었습니다.": "The gateway state changed. The update was canceled.",
  "게이트웨이가 중지되지 않았습니다. 업데이트가 취소되었습니다.": "The gateway has not stopped. The update was canceled.",
  "다른 게이트웨이가 해당 포트를 사용하고 있습니다. 먼저 런타임 설정을 확인하세요.": "Another gateway is using the port. Check the runtime settings first.",
  "추출된 업데이트가 크기 제한을 초과합니다.": "The extracted update exceeds the size limit.",
  "업데이트에 잘못된 경로가 포함되어 있습니다.": "The update contains an invalid path.",
  "업데이트에 중복된 경로가 포함되어 있습니다.": "The update contains duplicate paths.",
  "업데이트에 지원되지 않는 파일이 포함되어 있습니다.": "The update contains an unsupported file.",
  "업데이트에 잘못된 링크가 포함되어 있습니다.": "The update contains an invalid link.",
  "업데이트 링크는 설치 외부를 가리킵니다.": "An update link points outside the installation.",
  "업데이트는 링크를 통해 쓰기를 시도합니다.": "The update attempts to write through a link.",

  "계속하려면 연결하세요": "Connect to continue",
  "데스크톱 채팅 로드 중…": "Loading desktop chat…",
  "자동으로 연결; 컴퓨터의 Codex에서 채팅이 열릴 수 있습니다.": "Connecting automatically; this may open the chat in Codex on your computer.",
  "아직 연결되지 않았습니다. 기록을 읽거나 다시 연결할 수 있습니다.": "Not connected yet. You can read history or reconnect.",
  "Codex 채팅 데이터베이스를 일시적으로 사용할 수 없습니다. 데스크톱 Codex를 열고 다시 시도하세요.": "Codex chat database is temporarily unavailable. Open desktop Codex and retry.",
  "Codex가 채팅 데이터베이스를 업데이트 중입니다. 잠시 후 다시 시도해 주세요.": "Codex is updating its chat database. Please retry shortly.",
  "지금은 Codex 채팅 데이터베이스를 읽을 수 없습니다. 잠시 다시 시도하거나 데스크톱 Codex를 다시 열어보세요.": "Cannot read the Codex chat database right now. Retry shortly or reopen desktop Codex.",
  "게이트웨이가 중지 중입니다. 아무것도 전송되지 않았습니다. 나중에 다시 시도해 주세요.": "The gateway is stopping. Nothing was sent; please try again later.",
  "데스크톱 Codex가 아직 이 채팅을 로드하는 중입니다. 아무것도 전송되지 않았습니다. 잠시 후 다시 시도해 주세요.": "Desktop Codex is still loading this chat. Nothing was sent; please try again shortly.",
  "데스크톱 Codex에서 채팅을 로드할 수 없습니다. 아무것도 전송되지 않았습니다. Codex가 설치되어 실행 중인지 확인하세요.": "Could not load the chat in desktop Codex. Nothing was sent; check that Codex is installed and running.",
  "스캔하여 로그인": "Scan to sign in",
  "QR 코드 새로 고침": "Refresh QR code",
  "연결을 확인하고 QR 코드를 생성하는 중…": "Checking the connection and generating a QR code\u2026",
  "휴대폰이 로그인되었습니다. 이 QR 코드는 더 이상 유효하지 않습니다.": "Phone signed in. This QR code is no longer valid.",
  "QR 코드가 만료되었습니다. 새로고침하세요.": "QR code expired. Please refresh.",
  "만료 날짜:": "Expires in: ",
  "스캔을 사용하여 모바일 앱에 연결하여 게이트웨이 비밀번호 없이 로그인하거나 휴대폰 카메라로 스캔하여 브라우저에서 엽니다. 휴대전화가 이 주소에 접속할 수 있어야 합니다.": "Use Scan to connect in the mobile App to sign in without a gateway password, or scan with your phone camera to open in a browser. Your phone must be able to reach this address.",
  "5분간 유효하며 1회 사용 가능합니다. 이 코드가 있으면 누구나 로그인할 수 있습니다. 비공개로 유지하세요. 축소하거나 새로 고치면 취소됩니다. 모바일 앱은 로그인된 장치에서 로그아웃하거나 취소할 때까지 로그인 상태를 유지합니다. 브라우저는 구성된 세션 기간을 따릅니다.": "Valid for 5 minutes and one use. Anyone with this code can sign in: keep it private. Collapsing or refreshing revokes it. The mobile App stays signed in until you sign out or revoke it in Signed-in devices. Browsers follow the configured session duration.",
  "이 QR 코드는 만료되었거나 이미 사용되었습니다. 컴퓨터에서 새로 고치거나 사용자 이름과 비밀번호로 로그인하세요.": "This QR code has expired or was already used. Refresh it on your computer, or sign in with your username and password.",
  "루프백 주소는 전화기에서 사용할 수 없습니다. LAN 또는 공용 연결을 활성화합니다.": "Loopback addresses cannot be used from a phone. Enable a LAN or public connection.",
  "QR 로그인을 활성화하려면 게이트웨이를 다시 시작하세요.": "Restart the gateway to enable QR sign-in",
  "QR 코드를 생성하기 전에 게이트웨이를 시작하세요.": "Start the gateway before generating a QR code",
  "이 주소는 현재 게이트웨이를 가리키지 않습니다. 연결 설정을 확인하세요.": "This address does not point to the current gateway. Check the connection settings.",
  "QR 로그인 작업이 실패했습니다.": "QR sign-in operation failed",
  "QR 로그인 작업 시간이 초과되었습니다. 다시 시도해 주세요.": "QR sign-in operation timed out. Please try again.",
  "시도 횟수가 너무 많습니다. 5분 후에 다시 시도하세요.": "Too many attempts. Try again in 5 minutes.",
  "요청 출처는 허용되지 않습니다.": "Request origin is not allowed",

