  "■ 정지": "■ Stop",
  ". 아래에서 임의의 주제를 생성하고 ntfy 전화 앱에서 정확한 주제를 구독하세요. 주제는 자동으로 생성됩니다.": ". Generate a random topic below and subscribe to that exact topic in the ntfy phone app. Topics are created automatically.",
