  "파일 변경을 허용하시겠습니까?": "Allow file changes?",
  "LAN 액세스 허용": "Allow LAN access",
  "이번 차례에 권한을 허용하시겠습니까?": "Allow permissions for this turn?",
  "이 명령을 허용하시겠습니까?": "Allow this command?",
  "휴대폰과 컴퓨터가 정확히 동일한 서버와 주제를 사용하는지 확인하세요. 접근이 거부되면 토큰 및 주제 권한을 확인하거나 익명 테스트를 위해 새로운 무작위 주제를 시도해보세요.": "Confirm that the phone and computer use exactly the same server and topic. If access is denied, check the token and topic permissions, or try a new random topic for an anonymous test.",
  "비밀번호 없는 액세스": "Passwordless access",
  "이 항목은 현재 게이트웨이에 도달하지 않습니다. 프록시 대상을 확인하십시오. 먼저 이전 게이트웨이를 업데이트하고 다시 시작하세요.": "This entry does not reach the current gateway. Check the proxy target; update and restart older gateways first",
  "항목이 게이트웨이 응답을 반환하지 않았습니다. 프록시 대상 확인": "The entry did not return a gateway response. Check the proxy target",
  "공개 익명 주제에는 액세스 제어가 없습니다. 주제를 아는 사람은 누구나 읽고 게시할 수 있습니다. 긴 임의의 이름을 사용하고 첫 번째 테스트에서는 채팅 제목을 숨기십시오. 정기적인 사용을 위해 보호된 주제를 고려하십시오.": "Public anonymous topics have no access control: anyone who knows the topic can read and publish. Use a long random name and keep chat titles hidden for the first test. Consider a protected topic for regular use.",
  "공개 익명 주제의 경우 토큰을 비워 두세요. 알림을 활성화하고 설정을 저장한 다음 테스트 알림을 보냅니다. 휴대폰으로 영수증을 확인하세요.": "Leave the token empty for a public anonymous topic. Enable notifications, save settings, then send a test notification. Confirm receipt on your phone.",
  "전화 채팅에서 미리 알림을 열어 구독하고 선택적으로 해당 채팅에 대한 완료 알림을 활성화하세요. 페이지를 닫은 후에도 모니터링은 계속됩니다. 중지하려면 알림을 끄세요.": "Open Reminders in a phone chat to subscribe and optionally enable completion notifications for that chat. Monitoring continues after closing the page; turn reminders off to stop.",
