  "취소": "Cancel",
  "LAN, 임시 Cloudflare 및 여러 고정 항목을 함께 실행할 수 있습니다. 모든 항목은 동일한 컴퓨터 게이트웨이에 도달하고 동일한 로그인을 사용합니다.": "LAN, temporary Cloudflare and multiple fixed entries can run together. Every entry reaches the same computer gateway and uses the same login.",
