  "동일한 SSH 대상에 대한 각 연결에는 서로 다른 루프백 포트가 필요합니다.": "Each connection to the same SSH target needs a different loopback port",
  "시작 및 데이터 디렉터리": "Startup and data directory",
  "시작": "Starting",
  "게이트웨이 시작 중": "Start gateway",
  "임시 HTTPS 터널은 게이트웨이로 시작됩니다. 런타임 설정에서 cloudflared를 선택합니다. URL는 변경될 수 있습니다. 게이트웨이당 하나의 임시 항목만 필요합니다. 고정 항목이 함께 실행될 수 있습니다.": "A temporary HTTPS tunnel starts with the gateway. Select cloudflared under Runtime settings. The URL may change. Only one temporary entry is needed per gateway; fixed entries can run alongside it.",
  "게이트웨이를 시작하고 전화 페이지를 새로 고치고 채팅을 엽니다. 알림을 열고 채팅 알림을 활성화한 후 저장하세요. 그런 다음 Codex에게 선택 사항을 제시하도록 요청하세요. 휴대폰을 잠그고 알림을 확인하세요.": "Start the gateway, refresh the phone page and open a chat. Open Reminders, enable chat reminders and save. Then ask Codex to present a choice. Lock your phone and check for the notification.",
