  "이 컴퓨터에서 실행 중": "Running on this computer",
  "데스크톱 앱에 저장된 프로젝트에 빈 채팅을 만든 다음 휴대폰에서 메시지를 보내세요. 컴퓨터에서 이 채팅이 열립니다.": "Create an empty chat in a project saved in the desktop App, then send messages from your phone. The computer will open this chat.",
