  "잘못된 주소 포트": "Invalid address port",
  "게이트웨이 포트를 사용하여 NAS에서 연결할 수 있는 컴퓨터의 HTTP 주소를 입력합니다. LAN 액세스를 활성화합니다. 네트워크가 서로 연결할 수 없는 경우 먼저 경로를 설정하거나 SSH 서버 연결을 사용하십시오.": "Enter the computer's HTTP address as reachable from the NAS, using the gateway port. Enable LAN access. If the networks cannot reach each other, establish a route first or use an SSH server connection.",
