  "알림을 활성화하기 전에 ntfy 주제를 입력하세요.": "Enter an ntfy topic before enabling notifications",
  "저장된 기록을 표시합니다. 데스크톱 앱에서 이 채팅을 열고 다시 연결하세요.": "Showing saved history. Open this chat in the desktop App, then reconnect.",
  "이 게이트웨이 버전은 알림을 지원하지 않습니다. 개요에서 중지했다가 다시 시작한 다음 전화 페이지를 새로 고치세요.": "This gateway version does not support reminders. Stop and restart it from the overview, then refresh the phone page.",
  "이 게이트웨이 버전은 이전 버전입니다. 알림 지원을 활성화하려면 다시 시작하세요.": "This gateway version is older. Restart it to enable notification support.",
  "확인 대기 중": "Pending confirmation",
  "보류 중인 확인에 대한 알림": "Notifications for pending confirmations",
  "수동으로 입력한 클릭 URL가 우선순위를 갖습니다. 고정 도메인을 자동으로 팔로우하려면 비워두세요. 채팅 제목과 내용은 기본적으로 제외됩니다. 이전 알림에 만료된 임시 링크가 있을 수 있습니다. 자체 호스팅 ntfy는 즉각적인 iPhone 알림을 위해 APN 업스트림이 필요합니다.": "A manually entered click URL takes priority. Leave it empty to follow a fixed domain automatically. Chat titles and content are excluded by default. Old notifications may have expired temporary links. Self-hosted ntfy needs an APNs upstream for instant iPhone notifications.",
  "시청 중인 채팅은 전화 페이지가 닫힌 후에도 계속 알림을 보냅니다.": "Watched chats keep sending reminders after the phone page is closed.",
