  "실행이 완료되면 알림": "Notify when a run completes",
  "확인이나 답변이 필요할 때 알립니다. 페이지를 닫은 후에도 모니터링이 계속됩니다.": "Notify when confirmation or a reply is needed. Monitoring continues after you close the page.",
  "이 채팅에만 적용됩니다. 중지되거나 실패한 실행을 제외하고 성공적인 완료를 알립니다.": "Applies to this chat only. Notify on successful completion, excluding stopped or failed runs.",
  "채팅 알림 설정이 저장되었습니다.": "Chat notification settings saved",
