  "ntfy 전송에 실패했습니다. 활성화된 동안 완료 알림이 다시 시도됩니다. 확인 알림은 보류 중에만 재시도됩니다. 서버, 인증, 네트워크를 확인하세요.": "ntfy delivery failed. Completion notifications retry while enabled; confirmation notifications retry only while pending. Check the server, authentication and network.",
