  "게이트웨이당 하나의 임시 Cloudflare 항목만 필요합니다. 다른 연결 유형을 동시에 활성화할 수 있습니다.": "Only one temporary Cloudflare entry is needed per gateway. Other connection types can be enabled at the same time",
