  "채팅을 찾을 수 없습니다.": "No chats found.",
  "테스트 알림은 전화 배송만 확인합니다. 채팅 알림에는 컴퓨터, 게이트웨이, 원본 Codex 앱 및 온라인 상태를 유지하는 데 필요한 SSH 연결도 필요합니다.": "The test notification checks phone delivery only. Chat reminders also need the computer, gateway, original Codex App and any required SSH connection to stay online.",
  "메시지": "Message",
  "메시지가 전달되었을 수 있습니다. 채팅 기록을 확인하세요. 다시 클릭하면 두 번 제출되지 않습니다.": "The message may have been delivered. Check the chat history; clicking again will not submit it twice.",
