  "업스트림 포트는 게이트웨이 수신 포트와 일치해야 합니다.": "The upstream port must match the gateway listening port",
  "컴퓨터에서 채팅": "Chat on your computer",
  "컴퓨터는 캠퍼스 네트워크를 포함하여 SSH를 통해 서버에 연결됩니다. 기존 SSH 키 또는 ssh-agent를 사용합니다. 먼저 터미널에서 호스트 지문을 확인하세요. 동일한 서버에 대한 서로 다른 연결에는 서로 다른 루프백 포트가 필요합니다.": "The computer connects out to your server over SSH, including from campus networks. Uses existing SSH keys or ssh-agent; verify the host fingerprint in a terminal first. Different connections to the same server need different loopback ports.",
  "컴퓨터에서 실행 · 휴대폰에서 계속": "Runs on your computer · Continues on your phone",
  "고정된 HTTPS 항목을 선호하고 임시 HTTPS 또는 LAN를 선호하려면 비워 두세요.": "Leave empty to prefer a fixed HTTPS entry, then temporary HTTPS or LAN",
  "현재 비밀번호를 유지하려면 비워 두세요. 최소 12자": "Leave empty to keep the current password; at least 12 characters",
  "자동 검색을 위해 비워 두세요.": "Leave empty for automatic discovery",
