  "에 대한": "About ",
  "재설정될 때까지": " until reset",
  "새로고침을 기다리는 중": "Waiting for refresh",
  "사용량 재설정": "Usage resets",
  "사용량 재설정 정보를 확인할 수 없습니다.": "Usage reset information is not available",
  "사용 가능:": "Available: ",
  "먼저 Codex 데스크톱 설정에서 사용량 재설정을 허용하세요.": "Allow usage resets in Codex desktop settings first",
  "이전 재설정 결과가 확인되지 않았습니다. 동일한 요청을 다시 시도하십시오.": "The previous reset result is unconfirmed. Retry the same request.",
  "동일한 요청을 다시 시도하세요.": "Retry the same request",
  "한 번의 재설정을 사용하십시오.": "Use one reset",
  "만료 기간이 제공되지 않음": "No expiry provided",
  "만료 시간:": "Expires at: ",
  "재설정 사용": "Use reset",
  "재설정 세부정보를 확인할 수 없습니다. 새로고침하고 다시 시도하세요.": "Reset details are unavailable. Refresh and try again.",
  "업데이트 날짜:": "Updated at: ",
  "동일한 재설정 요청을 다시 시도하시겠습니까?": "Retry this same reset request?",
  "한 번의 사용량 재설정을 사용하시겠습니까?": "Use one usage reset?",
  "성공하면 한 번의 재설정이 필요하고 적격 계정 한도가 복원됩니다.": "Success consumes one reset and restores eligible account limits.",
  "재설정이 사용되었습니다. 사용량 한도가 새로고침되었습니다.": "Reset used. Usage limits refreshed.",
  "이 재설정은 이미 완료되었습니다. 사용량 한도가 새로고침되었습니다.": "This reset was already completed. Usage limits refreshed.",
  "재설정할 수 있는 사용 기간이 없습니다.": "There is no eligible usage window to reset",
  "사용량 재설정이 불가능합니다.": "No usage resets are available",
  "재설정 결과를 확인하려면 새로고침하세요.": "Refresh to check the reset result",
  "Codex 계정 서비스에 연결할 수 없습니다. 데스크톱 로그인을 확인하세요.": "Cannot connect to the Codex account service. Check desktop sign-in.",
  "Codex 계정 서비스 연결이 끊어졌습니다. 새로고침하고 다시 시도하세요.": "The Codex account service disconnected. Refresh and try again.",
  "계정 작업이 실패했습니다. 데스크톱 로그인을 확인하거나 데스크톱 앱을 업데이트하세요.": "Account operation failed. Check desktop sign-in or update the desktop app.",
  "계정 요청 시간이 초과되었거나 연결이 끊어졌습니다. 새로고침하고 다시 시도하세요.": "The account request timed out or disconnected. Refresh and retry.",
  "재설정을 사용하기 전에 확인하세요.": "Confirm before using a reset",
  "잘못된 재설정 요청 ID": "Invalid reset request ID",
  "계정 정보를 새로고침하고 다시 시도하세요.": "Refresh account information and try again",
  "잘못된 사용량 재설정 ID": "Invalid usage reset ID",
  "사용량을 재설정하려면 네이티브 ChatGPT 로그인이 필요합니다.": "Usage resets require native ChatGPT sign-in",
  "데스크톱 계정이 변경되었습니다. 새로고침하고 다시 확인하세요.": "The desktop account changed. Refresh and confirm again.",
  "재설정 요청은 다른 계정에 재사용하거나 재설정할 수 없습니다.": "A reset request cannot be reused for a different account or reset",
  "마지막 재설정이 확인되지 않았습니다. 동일한 요청을 새로 고치고 다시 시도하세요.": "The last reset is unconfirmed. Refresh and retry the same request.",
